 packpath=HERE/'resolved_placements.json';pack=json.loads(packpath.read_text());road=next(r for r in DATA['roads'] if r['id']=='RESERVOIR_SERVICE');a=road['polyline_xz_m'][-1];points=[a,[-31,-331.7],[-33.2,-333.7],[-33.4,-335.7167708839214]];width=1.4;polys=[geo.road_ribbon(p,q,width) for p,q in zip(points,points[1:])];existing=[{'polygon_xz_m':f['polygon_xz_m']} for f in pack['owned_floors']]+[{'polygon_xz_m':geo.road_ribbon(p,q,road['width_m'])} for p,q in zip(road['polyline_xz_m'],road['polyline_xz_m'][1:])];cut=DomainCut(existing);pieces=[]
 for i,poly in enumerate(polys):
  for j,q in enumerate(cut.subtract(poly)):
   heights=[water.height_at(*v) for v in q];pieces.append({'id':f'RESERVOIR_SERVICE:FINITE_HANDOFF:{i}:{j}','polygon_xz_m':q,'finished_y_m':18,'underlying_vertex_y_m':heights,'maximum_sampled_fill_m':max(18-y for y in heights),'maximum_sampled_cut_m':max(y-18 for y in heights),'bottom_policy':'Finite retaining/cut-fill closure to existing land; outside this mask source heights stay unchanged.'})
 wet=water.finite_water_polygons();wetarea=sum(geo.intersection_area(p['polygon_xz_m'],w['polygon_xz_m']) for p in pieces for w in wet);assert wetarea<1e-8
 value={'schema':'riverstone.city.reservoir_public_handoff_proposal.v1','base_pack':ref(packpath),'source_plan':pack['source_plan'],'water_contract':ref(CONTRACT),'replaces_proposal_ids':['RESERVOIR_DRAWPOINT_SERVICE'],'replacement_route':{'id':'RESERVOIR_DRAWPOINT_SERVICE','width_m':width,'points_xyz_m':[[x,18,z] for x,z in points],'public_target_id':'RESERVOIR_SERVICE','end_role':'Clear outer working platform east of the wellhouse; manual draw interaction is separate.','status':'Finite proposal awaiting terrain activation and independent native capsule audit.'},'terrain_owned_handoff_pieces':pieces,'new_surface_area_m2':sum(geo.polygon_area(p['polygon_xz_m']) for p in pieces),'wet_overlap_m2':wetarea,'native_asset_or_placement_changes':False,'source_road_changes':False,'source_proposal_endpoint_change':'The1.4m ribbon stops atX-33.4, outside the windlass working envelope. The olderX-34.2 proposal is not approved as a1.4m-wide corridor.','activation_status':'Not part of the sealed r08 terrain wrapper; explicit follow-on required.'};write(HERE/'public_access_handoff.json',value);print(json.dumps({'path':ref(HERE/'public_access_handoff.json'),'pieces':len(pieces),'new_surface_area_m2':value['new_surface_area_m2'],'maximum_sampled_fill_m':max(p['maximum_sampled_fill_m'] for p in pieces),'maximum_sampled_cut_m':max(p['maximum_sampled_cut_m'] for p in pieces)},indent=2))
